import java.lang.reflect.Proxy;
import java.util.*;
import java.util.function.Supplier;

public class Main {
    interface Service { String name(); }

    static final class A implements Service {
        Service b;
        public String name() { return "A->" + b.getClass().getSimpleName(); }
    }

    static final class B implements Service {
        Service a;
        public String name() { return "B->" + a.getClass().getName().contains("$Proxy"); }
    }

    static final class MiniBeanFactory {
        private final Map<String, Object> singletonObjects = new LinkedHashMap<>();
        private final Map<String, Object> earlySingletonObjects = new LinkedHashMap<>();
        private final Map<String, Supplier<Object>> singletonFactories = new LinkedHashMap<>();
        private final Set<String> creating = new HashSet<>();
        private final List<String> events = new ArrayList<>();

        Object getBean(String name) {
            Object singleton = singletonObjects.get(name);
            if (singleton != null) {
                return singleton;
            }
            if (creating.contains(name)) {
                return getEarlyReference(name);
            }
            return createBean(name);
        }

        private Object createBean(String name) {
            creating.add(name);
            Object raw = instantiate(name);
            events.add("instantiate " + name);
            singletonFactories.put(name, () -> createEarlyProxyIfNeeded(name, raw));
            events.add("put factory " + name);

            if (raw instanceof A a) {
                a.b = (Service) getBean("b");
                events.add("populate a.b");
            } else if (raw instanceof B b) {
                b.a = (Service) getBean("a");
                events.add("populate b.a with early A");
            }

            Object exposed = earlySingletonObjects.getOrDefault(name, raw);
            singletonObjects.put(name, exposed);
            earlySingletonObjects.remove(name);
            singletonFactories.remove(name);
            creating.remove(name);
            events.add("publish " + name + " proxy=" + Proxy.isProxyClass(exposed.getClass()));
            return exposed;
        }

        private Object instantiate(String name) {
            return switch (name) {
                case "a" -> new A();
                case "b" -> new B();
                default -> throw new IllegalArgumentException(name);
            };
        }

        private Object getEarlyReference(String name) {
            Object early = earlySingletonObjects.get(name);
            if (early != null) {
                events.add("hit level2 " + name);
                return early;
            }
            Supplier<Object> factory = singletonFactories.get(name);
            if (factory == null) {
                throw new IllegalStateException("constructor/prototype style cycle: no early reference for " + name);
            }
            Object created = factory.get();
            earlySingletonObjects.put(name, created);
            singletonFactories.remove(name);
            events.add("create early reference " + name + " proxy=" + Proxy.isProxyClass(created.getClass()));
            return created;
        }

        private Object createEarlyProxyIfNeeded(String name, Object raw) {
            if (!name.equals("a")) {
                return raw;
            }
            Service target = (Service) raw;
            return Proxy.newProxyInstance(
                    Service.class.getClassLoader(),
                    new Class<?>[]{Service.class},
                    (proxy, method, args) -> "proxy(" + target.name() + ")"
            );
        }

        Object raw(String name) {
            return switch (name) {
                case "a" -> null;
                case "b" -> singletonObjects.get("b");
                default -> null;
            };
        }

        List<String> events() { return events; }
    }

    public static void main(String[] args) {
        MiniBeanFactory factory = new MiniBeanFactory();
        Service a = (Service) factory.getBean("a");
        B b = (B) factory.getBean("b");
        System.out.println("aIsProxy=" + Proxy.isProxyClass(a.getClass()));
        System.out.println("bHoldsSameA=" + (b.a == a));
        System.out.println("callA=" + a.name());
        factory.events().forEach(System.out::println);
    }
}
